//     h = {"z": [3]}  # tpyc: type(dict[str, Array[int64, 1]])
//     g.update(h)  # tpyc: warning(/copies list\[int64\] elements/)
//     dd = {"a": {"x": 1}}  # tpyc: type(dict[str, dict[str, int64]])
//     dd["a"]["y"] = wide()
//     src = {"b": {"z": 1}}  # tpyc: type(dict[str, dict[str, int64]])
//     dd.update(src)  # tpyc: warning(/copies dict\[str, int64\] elements/)
//     print("update_rows:", g, h, dd, src)
void update_rows_pos() {
    ::tpy::ordered_map<std::string, std::array<int64_t, 1>> g = ::tpy::ordered_map<std::string, std::array<int64_t, 1>>({{"a", {1}}});
    ::tpy::__setitem__(g, "c", std::array<int64_t, 1>{::tpyapp::main::wide()});
    ::tpy::ordered_map<std::string, std::array<int64_t, 1>> h = ::tpy::ordered_map<std::string, std::array<int64_t, 1>>({{"z", {3}}});
    ::tpy::dict_update(g, h);
    ::tpy::ordered_map<std::string, ::tpy::ordered_map<std::string, int64_t>> dd = ::tpy::ordered_map<std::string, ::tpy::ordered_map<std::string, int64_t>>({{"a", ::tpy::ordered_map<std::string, int64_t>({{"x", 1}})}});
    ::tpy::__setitem__(::tpy::__getitem__(dd, "a"), "y", ::tpyapp::main::wide());
    ::tpy::ordered_map<std::string, ::tpy::ordered_map<std::string, int64_t>> src = ::tpy::ordered_map<std::string, ::tpy::ordered_map<std::string, int64_t>>({{"b", ::tpy::ordered_map<std::string, int64_t>({{"z", 1}})}});
    ::tpy::dict_update(dd, src);
    std::cout << "update_rows:" << " " << ::tpy::DictPrinter(g) << " " << ::tpy::DictPrinter(h) << " " << ::tpy::DictPrinter(dd) << " " << ::tpy::DictPrinter(src) << "\n" << ::tpy::check_signals;
}

